[37921] = {id=37921,name="Clearing the Docks",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=6721,mapID=543,description="Our salvage team thought these here docks would be abandoned, but they're crawlin' wit' remnants of the Iron Horde. Gul'dan's cronies are convertin' anyone they can and evacuatin' everyone to Tanaan Jungle. Commander, if yeh can clear this place out, my team can salvage some of this equipment. Plus, ev'ry orc yeh kill here is one less ta worry about in Tanaan!",objectivesText="Kill 1 Iron Horde orcs and 50 ogron.",questType="world",db2Objectives={{orderIndex=1,type=0,amount=50,objectID=90025,text="Iron Horde orcs slain"},{orderIndex=2,type=0,amount=17,objectID=89951,text="Ogron Slain"},{orderIndex=0,type=15,amount=1,objectID=0,text="Disrupt the Iron Horde Evacuation"},{orderIndex=5,type=0,amount=10,objectID=91596,text="Felsworn Prophet Slain"},{orderIndex=3,type=0,amount=17,objectID=93147,text="Transports Sunk"},{orderIndex=4,type=0,amount=17,objectID=93174,text="Siege Weapons Destroyed"}},worldTaskTitle="Clearing the Docks"},
[44570] = {id=44570,name="Honor the Flame",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6722,mapID=542,description="The Midsummer Fire Festival is a time to honor the elements. The element of fire stirs passion within us all. Many times, that passion pours out into aggressive actions. But here, in this land, we focus our passion on reverence. We will honor the flame as tradition dictates. Will you honor the flame with us, <name>?",objectivesText="Honor the Midsummer Bonfire in Spires of Arak.",starts={{mapID=542,npcID=114488,x=0.48,y=0.446}},ends={{mapID=542,npcID=114488,x=0.48,y=0.446}},coords={mapID=542,source="quest_giver",x=0.48,y=0.446},questType="world",worldTaskTitle="Honor the Flame"},
